import { Hono } from '/home/jack/.t3/bench-runs/2026-09-28-sonnet-5-5-rebench/att-055/clone/src/hono'
import { validator } from '/home/jack/.t3/bench-runs/2026-09-28-sonnet-5-5-rebench/att-055/clone/src/validator'

const mk = (kind: 'multi' | 'url') => {
  if (kind === 'multi') { const f = new FormData(); f.append('a', 'b'); return { method: 'POST', body: f } }
  const p = new URLSearchParams(); p.append('a', 'b')
  return { method: 'POST', body: p, headers: { 'content-type': 'application/x-www-form-urlencoded' } }
}
const run = async (name: string, app: Hono, kind: 'multi'|'url') => {
  const res = await app.request('/x', mk(kind) as RequestInit)
  console.log(name, kind, res.status, (await res.text()).slice(0, 200))
}
const safe = (f: any) => async (c: any) => { try { return c.json(await f(c)) } catch (e: any) { return c.text('ERR ' + e?.message, 500) } }
for (const kind of ['multi', 'url'] as const) {
  const a = new Hono(); a.post('/x', safe(async (c: any) => { const x = await c.req.parseBody(); const y = await c.req.parseBody(); return [x, y] }))
  await run('parseBody twice', a, kind)
  const b = new Hono(); b.post('/x', safe(async (c: any) => { const x = await c.req.parseBody(); const y = await c.req.formData(); return [x, [...y.entries()]] }))
  await run('parseBody then formData', b, kind)
  const c2 = new Hono(); c2.post('/x', validator('form', (v: any) => v), safe(async (c: any) => [c.req.valid('form'), await c.req.parseBody()]))
  await run('validator then parseBody', c2, kind)
  const d = new Hono(); d.post('/x', safe(async (c: any) => { const y = await c.req.formData(); const x = await c.req.parseBody(); return [[...y.entries()], x] }))
  await run('formData then parseBody', d, kind)
  const e = new Hono(); e.post('/x', safe(async (c: any) => { const t = await c.req.text(); const x = await c.req.parseBody(); return [t.slice(0,20), x] }))
  await run('text then parseBody', e, kind)
  const f = new Hono(); f.post('/x', safe(async (c: any) => { const x = await c.req.parseBody(); const t = await c.req.text(); return [x, t.slice(0,30)] }))
  await run('parseBody then text', f, kind)
}
EOF
